sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    var consumerID=g_form.getValue("consumer");

    if(newValue=="Advance" || newValue=="Permium"){
        var ga = new GlideAjax("CreateCarWashEntitlement");
        ga.addParam('sysparm_name', 'createEntitlement');
        ga.addParam('sysparm_plan', newValue);
        ga.addParam('sysparm_consumer', consumerID);

        ga.getXMLAnswer(function(response1) {
            if (response1 == "created") {
                g_form.addInfoMessage("Car Wash Entitlement created for " + newValue + " plan.");


            } else {
                g_form.addErrorMessage("Failed to create Car Wash Entitlement: " + response1);
            }
        });
	}

}
